import{_ as p,W as o,s as l,u as d,I as n,ah as r,w as s,Z as t,A as i}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const z=JSON.parse('{"title":"使用 Python 调整图像大小 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 调整图像大小 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 调整图像大小 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 调整图像大小 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20210101 Resize images using Python","title":"使用 Python 调整图像大小","tag":"202101"},"relativePath":"202101/20210101 Resize images using Python.md","filePath":"[post].md"}'),g={name:"202101/20210101 Resize images using Python.md"};function m(h,e,u,f,y,P){const a=o("Link");return d(),l("div",null,[e[20]||(e[20]=n("h1",{id:"使用-python-调整图像大小",tabindex:"-1"},[s("使用 Python 调整图像大小 "),n("a",{class:"header-anchor",href:"#使用-python-调整图像大小","aria-label":"Permalink to 使用 Python 调整图像大小"},"​")],-1)),e[21]||(e[21]=n("blockquote",null,[n("p",null,"快速解释如何在 Python 中调整图像大小，同时保持相同的长宽比。")],-1)),e[22]||(e[22]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life-python.jpg?itok=F2PYP2wT",alt:"Python in a tree",title:"Python in a tree"})],-1)),n("p",null,[e[2]||(e[2]=s("我喜欢 ")),t(a,{href:"http://python.org/",title:"Python Programming Language – Official Website"},{default:i(()=>e[0]||(e[0]=[s("Python")])),_:1}),e[3]||(e[3]=s("，而且我已经学了一段时间了。前段时间，我写了一个 Python 脚本，在这个脚本中，我需要调整一堆图片的大小，同时保持长宽比（比例）不变。于是我四处寻找，发现了 ")),t(a,{href:"https://pypi.org/project/Pillow/",title:"Python Imaging Library"},{default:i(()=>e[1]||(e[1]=[s("Pillow")])),_:1}),e[4]||(e[4]=s("，这是一个 Python 图像库，也是一个叫做 PIL 的旧库的“友好复刻”。"))]),e[23]||(e[23]=r(`<p>要安装 Pillow，请使用 Python 的 <code>pip</code> 模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ python3 -m pip install Pillow</span></span></code></pre></div><h3 id="按宽度缩放" tabindex="-1">按宽度缩放 <a class="header-anchor" href="#按宽度缩放" aria-label="Permalink to 按宽度缩放">​</a></h3><p>这是一个使用 Pillow 模块来调整图片大小的基本脚本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from PIL import Image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>basewidth = 300</span></span>
<span class="line"><span>img = Image.open(&#39;fullsized_image.jpg&#39;)</span></span>
<span class="line"><span>wpercent = (basewidth / float(img.size[0]))</span></span>
<span class="line"><span>hsize = int((float(img.size[1]) * float(wpercent)))</span></span>
<span class="line"><span>img = img.resize((basewidth, hsize), Image.ANTIALIAS)</span></span>
<span class="line"><span>img.save(&#39;resized_image.jpg&#39;)</span></span></code></pre></div><p>这几行 Python 代码使用 Pillow 将一张图片 （<code>fullsized_image.jpg</code>） 调整为 300 像素的宽度，宽度在变量 <code>basewidth</code> 中设置，高度则与新的宽度成比例。比例高度的计算方法是：确定 300 像素占原宽度 （<code>img.size[0]</code>） 的百分比，然后将原高度（<code>img.size[1]</code>） 乘以该百分比。所得的高度值保存在变量 <code>hsize</code> 中。</p><p>如果你需要不同的图片宽度，你可以将 <code>basewidth</code> 改为任何其他数字。另外，请注意，因为我想保留全尺寸的图片 （<code>fullsized_image.jpg</code>），因此我将调整后的图片以一个不同的名称 <code>resized_image.jpg</code> 保存。当然，你不必这么做。如果你想，你可以使用相同的文件名将调整后的图片覆盖全尺寸的图片。</p><h3 id="按高度缩放" tabindex="-1">按高度缩放 <a class="header-anchor" href="#按高度缩放" aria-label="Permalink to 按高度缩放">​</a></h3><p>如果高度是固定的，而宽度是按比例变化的，那也基本差不多，你只需要把东西换一下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from PIL import Image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>baseheight = 560</span></span>
<span class="line"><span>img = Image.open(&#39;fullsized_image.jpg&#39;)</span></span>
<span class="line"><span>hpercent = (baseheight / float(img.size[1]))</span></span>
<span class="line"><span>wsize = int((float(img.size[0]) * float(hpercent)))</span></span>
<span class="line"><span>img = img.resize((wsize, baseheight), Image.ANTIALIAS)</span></span>
<span class="line"><span>img.save(&#39;resized_image.jpg&#39;)</span></span></code></pre></div><p>注意 <code>basewidth</code> 现在换成了 <code>baseheight</code>，因为高度是固定的。在第三行中，我们在计算高度百分比，所以我们需要 <code>img.size[1]</code> 而不是 <code>img.size[0]</code>。<code>size</code> 属性是一个元组，包含宽度和高度，单位是像素，<code>size[0]</code> 指的是第一个元组元素，也就是宽度，<code>size[1]</code> 是第二个元素，也就是高度。第 4 行也有这样的切换，<code>size[0]</code> 代表宽度，<code>size[1]</code> 代表高度。</p><hr>`,12)),n("p",null,[e[6]||(e[6]=s("via: ")),t(a,{href:"https://opensource.com/life/15/2/resize-images-python"},{default:i(()=>e[5]||(e[5]=[s("https://opensource.com/life/15/2/resize-images-python")])),_:1})]),n("p",null,[e[11]||(e[11]=s("作者：")),t(a,{href:"https://opensource.com/users/dayontwari"},{default:i(()=>e[7]||(e[7]=[s("Dayo Ntwari")])),_:1}),e[12]||(e[12]=s(" 选题：")),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>e[8]||(e[8]=[s("lujun9972")])),_:1}),e[13]||(e[13]=s(" 译者：")),t(a,{href:"https://github.com/geekpi"},{default:i(()=>e[9]||(e[9]=[s("geekpi")])),_:1}),e[14]||(e[14]=s(" 校对：")),t(a,{href:"https://github.com/wxy"},{default:i(()=>e[10]||(e[10]=[s("wxy")])),_:1})]),n("p",null,[e[17]||(e[17]=s("本文由 ")),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>e[15]||(e[15]=[s("LCTT")])),_:1}),e[18]||(e[18]=s(" 原创编译，")),t(a,{href:"https://linux.cn/"},{default:i(()=>e[16]||(e[16]=[s("Linux中国")])),_:1}),e[19]||(e[19]=s(" 荣誉推出"))])])}const T=p(g,[["render",m]]);export{z as __pageData,T as default};
